    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>يلتزم جميع العاملين في المجال الطبي بغسل الأيدي بطريقة صحيحة تبعاً لنوع الإجراء لمنع انتقال الملوثات أثناء التعامل مع المرضى.</p><h3>أنواع غسيل الأيدي:</h3><ul><li><strong>1. الغسيل البسيط (الروتيني):</strong> بالماء الجاري والصابون لمدة (40 - 60 ثانية) قبل وبعد التعامل مع المريض، بعد خلع القفازات، وبعد لمس الأسطح أو الذهاب للحمام.</li><li><strong>2. غسل وتطهير اليدين (التطهير الصحية):</strong> باستخدام مطهر (بيتادين رغوي 7.5%) قبل الإجراءات الاختراقية البسيطة، الغيار على الجروح، ورعاية مرضى نقص المناعة، وخلط المحاليل.</li><li><strong>3. الدلك بالكحول (70% - 95%):</strong> لمدة (20 - 30 ثانية) وهو الطريقة الأنسب لتطهير الأيدي لأغلب الأنشطة الإكلينيكية بشرط أن تكون اليدان غير متسختين ظاهرياً.</li><li><strong>4. الغسل الجراحي لليدين:</strong> باستخدام بيتادين رغوي 7.5% لليدين والساعدين لما فوق الكوع لمدة (5 دقائق) قبل أول عملية في اليوم، و(3 - 5 دقائق) للعمليات التالية، والتجفيف بمنشفة معقمة.</li></ul><h3>نقاط هامة:</h3><ul><li>خلع جميع الخواتم والمجوهرات وتقليم الأظافر.</li><li>لا تستخدم أحواض غسيل الأيدي في غسل الآلات.</li><li>غلق الصنبور بالكوع أو بمنديل التجفيف.</li></ul></div>",
