        "slide_title": "تقديم رعاية موحدة دون تمييز (ICD.01)",
        "bullet_points": [
          "تقديم خدمات متماثلة للمرضى بغض النظر عن العرق أو اللغة أو المستوى الاجتماعي.",
          "الالتزام بتطبيق البروتوكولات الإكلينيكية المعتمدة في كافة أقسام المستشفى.",
          "توفير قنوات واضحة لتلقي والتحقيق في شكاوى التمييز إن وجدت."
        ]
