    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>تحديد الاحتياجات التمريضية للمريض من خلال التقييم الشامل عند الدخول وإعادة التقييم المستمر طوال فترة الإقامة.</p><h3>إجراءات التقييم التمريضي:</h3><ul><li>إجراء التقييم التمريضي الأولي فور وصول المريض وتوثيقه في نموذج تقييم الدخول (العلامات الحيوية، الحالة النفسية، التنقل، الإخراج، والحساسية).</li><li>تقييم مخاطر السقوط وقرح الفراش ومستوى الألم فور الدخول.</li><li>إعادة التقييم التمريضي في بداية كل شفت، أو عند حدوث أي تغير فجائي في حالة المريض الإكلينيكية.</li></ul></div>",
