    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>ضمان تقييم الحالة الغذائية لجميع المرضى المدخولين وتوفير الدعم الغذائي المناسب لحالتهم الصحية والإكلينيكية.</p><h3>إجراءات العمل:</h3><ul><li>إجراء التقييم الغذائي المبدئي لكل مريض عند الدخول لتحديد خطر سوء التغذية أو الاحتياجات الخاصة.</li><li>تحديد النظام الغذائي المناسب لكل مريض وكتابته في أوامر الطبيب بوضوح (سوائل، لين، مالح، مريض سكري، إلخ).</li><li>متابعة تقديم الوجبات والتنسيق مع أخصائي التغذية العلاجية لمراجعة الحالات التي تحتاج إلى تغذية أنبوبية أو وريدية خاصة.</li></ul></div>",
    "plain_text": "تقييم وإدارة الاحتياجات التغذوية تقييم الحالة الغذائية للمريض عند الدخول طلب الوجبات حسب حالة المريض الطبية إشراف أخصائي التغذية.",
