    "responsibilities": "جميع العاملين - موظفو الاستقبال - الأمن - التمريض",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>توفير بيئة رعاية شاملة ومتاحة بسهولة لمرضى ذوي الاحتياجات الخاصة وتسهيل حصولهم على كافة الخدمات الطبية دون عقبات.</p><h3>إجراءات العمل:</h3><ul><li>توفير الكراسي المتحركة والمنحدرات والممرات الملائمة لتنقل ذوي الاحتياجات الخاصة.</li><li>إعطاء الأولوية في التسجيل والكشف والفحوصات للمرضى من ذوي الاحتياجات الخاصة وكبار السن.</li><li>مساعدة المرافقين والمريض في إنهاء كافة الإجراءات الإدارية والتمريضية بيسر واحترام.</li></ul></div>",
