    "responsibilities": "الأطباء - هيئة التمريض",
    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>تنظيم عملية كتابة وتنفيذ وتوثيق الأوامر والطلبات الطبية لضمان سلامة المرضى ومنع الأخطاء الدوائية أو الإجرائية.</p><h3>إجراءات العمل:</h3><ul><li>يجب أن تُكتب كافة الأوامر الطبية (أدوية، فحوصات، إجراءات) بوضوح في نموذج 'أوامر الطبيب' المعتمد بالملف الطبي.</li><li>تتضمن الأمر الطبي بوضوح: اسم الدواء، الجرعة، طريقة الإعطاء، والتوقيت، مع توقيع الطبيب وتاريخ وساعة الكتابة.</li><li>يقوم التمريض بمراجعة الأوامر وتوقيع التنفيذ فور الإعطاء مع الالتزام بقواعد منع الأخطاء.</li></ul></div>",
    "plain_text": "أوامر وطلبات الطبيب كتابة الأوامر بوضوح وتوقيعها كتابة الأدوية والجرعات والتوقيتات بالنموذج المعتمد.",
