    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>ضمان حصول المريض أو ممثله القانوني على شرح كامل ومبسط للإجراءات الطبية والجراحية المقترحة ومخاطرها وبدائلها قبل أخذ التوقيع على إقرار الموافقة المستنيرة.</p><h3>إجراءات العمل:</h3><ul><li>يقوم الطبيب المعالج بشرح طبيعة الإجراء، الفوائد، المخاطر المحتملة، والبدائل المتاحة بلغة يفهما المريض.</li><li>توقيع المريض أو ممثله القانوني على إقرار الموافقة المستنيرة قبل البدء بأي إجراء تداخلي أو جراحي.</li><li>تكون صلاحية إقرار الموافقة سارية لفترة محددة طبقاً للوائح (غالباً خلال فترة الإقامة الحالية أو ما لم تتغير الحالة الإكلينيكية جوهرياً).</li></ul></div>",
    "plain_text": "الموافقة المستنيرة Informed Consent شرح الإجراءات والمخاطر والبدائل صلاحية الإقرار.",
