    "content_html": "<div class='policy-doc'><h3>السياسة والغرض:</h3><p>ضمان مراجعة واعتماد وتوزيع وتحديث كافة السياسات والأدلة الإكلينيكية والإدارية بشكل منظم يمنع استخدام نسخ قديمة أو ملغاة.</p><h3>إجراءات العمل:</h3><ul><li>تخضع كل سياسة ومستند لعملية إعداد، مراجعة من الجودة، واعتماد رسمي من مدير المستشفى ورئيس القسم.</li><li>وضع رقم إصدار وتاريخ تفعيل وتاريخ مراجعة قادم على كل مستند رسمي.</li><li>سحب وإلغاء أي نسخ ورقية قديمة فور صدور التحديثات لضمان اعتماد النسخة السارية فقط.</li></ul></div>",
    "plain_text": "التحكم بالوثائق ضبط المستندات إصدار وتعديل ومراجعة السياسات وإلغاء النسخ القديمة.",
